```tsx
function ShopContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const catParam = searchParams.get('category') ?? '';
  const qParam = searchParams.get('q') ?? '';
  const pageParam = Number(searchParams.get('page')) || 1;
  const [category, setCategory] = useState(catParam);
  const [q, setQ] = useState(qParam);
  const [appliedQ, setAppliedQ] = useState(qParam);
  const [page, setPage] = useState(pageParam);
  const [data, setData] = useState<ProductList | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [categories, setCategories] = useState<string[]>(CATEGORIES);

  // debounce q
  useEffect(() => {
    const t = setTimeout(() => setAppliedQ(q), 300);
    return () => clearTimeout(t);
  }, [q]);

  // update URL when filters change (skip on first render)
  const first = useRef(true);
  useEffect(() => {
    if (first.current) { first.current = false; return; }
    const params = new URLSearchParams();
    if (category) params.set('category', category);
    if (appliedQ) params.set('q', appliedQ);
    if (page > 1) params.set('page', String(page));
    const qs = params.toString();
    router.replace(qs ? `/shop?${qs}` : '/shop', { scroll: false });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [category, appliedQ, page]);

  // fetch
  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    const params = new URLSearchParams();
    if (category) params.set('category', category);
    if (appliedQ) params.set('q', appliedQ);
    params.set('page', String(page));
    params.set('pageSize', '12');
    fetch(`/api/products?${params}`)
      .then((r) => r.json())
      .then((json) => { if (!cancelled) { if (json.ok) { setData(json.data); setError(null);} else setError(json.error ?? 'Failed to load products.'); } })
      .catch(() => { if (!cancelled) setError('Network error — please try again.'); })
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, [category, appliedQ, page]);
  ...
```

