'use client';

import { Suspense, useCallback, useEffect, useRef, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import ProductCard from '@/components/site/product-card';
import { CATEGORIES } from '@/lib/catalog';
import type { Product } from '@/lib/store';

interface ProductListData {
  items: Product[];
  total: number;
  page: number;
  pageSize: number;
  totalPages: number;
  categories: string[];
}

function ShopContent() {
  const router = useRouter();
  const searchParams = useSearchParams();

  const catParam = searchParams.get('category') ?? '';
  const qParam = searchParams.get('q') ?? '';
  const pageParam = Math.max(1, Number(searchParams.get('page')) || 1);

  const [category, setCategory] = useState(catParam);
  const [q, setQ] = useState(qParam);
  const [appliedQ, setAppliedQ] = useState(qParam);
  const [page, setPage] = useState(pageParam);
  const [data, setData] = useState<ProductListData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Debounce the search query.
  useEffect(() => {
    const t = setTimeout(() => setAppliedQ(q), 300);
    return () => clearTimeout(t);
  }, [q]);

  // Mirror filter changes to the URL (skipping the first render).
  const firstRender = useRef(true);
  useEffect(() => {
    if (firstRender.current) {
      firstRender.current = false;
      return;
    }
    const params = new URLSearchParams();
    if (category) params.set('category', category);
    if (appliedQ) params.set('q', appliedQ);
    if (page > 1) params.set('page', String(page));
    const qs = params.toString();
    router.replace(qs ? `/shop?${qs}` : '/shop', { scroll: false });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [category, appliedQ, page, router]);

  // Fetch the product list whenever filters change.
  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    const params = new URLSearchParams();
    if (category) params.set('category', category);
    if (appliedQ) params.set('q', appliedQ);
    params.set('page', String(page));
    params.set('pageSize', '12');

    fetch(`/api/products?${params.toString()}`)
      .then((res) => (res.ok ? res.json() : Promise.reject(new Error('Request failed'))))
      .then((json) => {
        if (cancelled) return;
        if (json.ok) {
          setData(json.data as ProductListData);
        } else {
          setError(json.error ?? 'Failed to load products.');
        }
      })
      .catch(() => {
        if (!cancelled) setError('Could not load products — please try again.');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [category, appliedQ, page]);

  const changeCategory = useCallback((value: string) => {
    setCategory(value);
    setPage(1);
  }, []);

  const changeSearch = useCallback((value: string) => {
    setQ(value);
    setPage(1);
  }, []);

  const goToPage = useCallback((p: number) => {
    setPage(p);
    if (typeof window !== 'undefined') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  }, []);

  const visibleCategories = data?.categories ?? CATEGORIES;

  return (
    <main id="main">
      {/* Hero */}
      <section className="bg-bg-secondary">
        <div className="mx-auto max-w-7xl px-4 py-14 sm:px-6 lg:py-20">
          <p className="text-sm font-semibold uppercase tracking-[0.2em] text-brand">
            Northlight Goods
          </p>
          <h1 className="mt-3 text-4xl sm:text-5xl">Shop our collection</h1>
          <p className="mt-4 max-w-xl text-lg text-text-secondary">
            Furniture, lighting, textiles, tableware and decor. Free US shipping on orders
            over $100 — otherwise a flat $8.
          </p>
        </div>
      </section>

      <section className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8">
        {/* Filters */}
        <div className="flex flex-wrap items-center gap-3 rounded-xl border border-border bg-white p-3 shadow-soft">
          <label htmlFor="shop-search" className="sr-only">
            Search products
          </label>
          <input
            id="shop-search"
            type="search"
            value={q}
            onChange={(e) => changeSearch(e.target.value)}
            placeholder="Search products…"
            className="field min-h-[44px] max-w-xs flex-1"
            autoComplete="off"
          />
          <label htmlFor="shop-category" className="sr-only">
            Filter by category
          </label>
          <select
            id="shop-category"
            value={category}
            onChange={(e) => changeCategory(e.target.value)}
            className="field min-h-[44px] w-full sm:w-auto"
          >
            <option value="">All categories</option>
            {visibleCategories.map((c) => (
              <option key={c} value={c}>
                {c}
              </option>
            ))}
          </select>
        </div>

        <p className="mt-6 text-sm text-text-secondary" aria-live="polite">
          {loading ? 'Loading products…' : `${data?.total ?? 0} product${(data?.total ?? 0) === 1 ? '' : 's'}`}
          {appliedQ ? ` for “${appliedQ}”` : ''}
          {category ? ` in ${category}` : ''}
        </p>

        {error ? (
          <div className="mt-8 rounded-xl border border-error/25 bg-error/5 p-6 text-error" role="alert">
            {error}
          </div>
        ) : (
          <>
            <div className="mt-4 grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
              {data?.items.map((product) => (
                <ProductCard key={product.id} product={product} />
              ))}
            </div>

            {!loading && data && data.items.length === 0 && (
              <div className="mt-16 text-center">
                <p className="text-2xl font-display text-text-primary">No products found</p>
                <p className="mt-2 text-text-secondary">
                  Try a different search or category.
                </p>
                <button
                  type="button"
                  className="btn btn-secondary mt-6"
                  onClick={() => {
                    setQ('');
                    setAppliedQ('');
                    changeCategory('');
                  }}
                >
                  Clear filters
                </button>
              </div>
            )}

            {data && data.totalPages > 1 && (
              <nav className="mt-12 flex items-center justify-center gap-2" aria-label="Pagination">
                <button
                  type="button"
                  className="btn btn-secondary btn-sm"
                  disabled={page <= 1}
                  onClick={() => goToPage(page - 1)}
                >
                  Previous
                </button>
                <span className="min-w-[88px] text-center text-sm text-text-secondary" aria-live="polite">
                  Page {data.page} of {data.totalPages}
                </span>
                <button
                  type="button"
                  className="btn btn-secondary btn-sm"
                  disabled={page >= data.totalPages}
                  onClick={() => goToPage(page + 1)}
                >
                  Next
                </button>
              </nav>
            )}
          </>
        )}
      </section>
    </main>
  );
}

export default function ShopPage() {
  return (
    <Suspense fallback={<div className="min-h-[50vh]" />}>
      <ShopContent />
    </Suspense>
  );
}

'use client';

import { useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { formatCents } from '@/lib/format';
import { galleryImages } from '@/lib/catalog';
import { useCart } from '@/components/cart/cart-provider';
import ProductCard from '@/components/site/product-card';
import Stars from '@/components/site/stars';
import type { Product } from '@/lib/store';

interface Review {
  name: string;
  role: string;
  rating: number;
  text: string;
}

const REVIEW_POOL: Review[] = [
  {
    name: 'Claire M.',
    role: 'Verified buyer',
    rating: 5,
    text: 'Exactly as pictured and better in person. The quality is obvious the moment you unpack it.',
  },
  {
    name: 'Jordan T.',
    role: 'Verified buyer',
    rating: 4,
    text: 'Really well made and arrived sooner than expected. Would buy from Northlight again without hesitation.',
  },
  {
    name: 'Samira K.',
    role: 'Verified buyer',
    rating: 5,
    text: 'Beautiful finish and the details are thoughtful — you can tell someone actually cared when designing this.',
  },
];

function pickReviews(productId: number): Review[] {
  const start = productId % REVIEW_POOL.length;
  return [
    REVIEW_POOL[start],
    REVIEW_POOL[(start + 1) % REVIEW_POOL.length],
    REVIEW_POOL[(start + 2) % REVIEW_POOL.length],
  ];
}

export default function ProductDetailPage() {
  const params = useParams<{ id: string }>();
  const id = Number(params.id);
  const { addItem } = useCart();

  const [product, setProduct] = useState<Product | null>(null);
  const [related, setRelated] = useState<Product[]>([]);
  const [notFound, setNotFound] = useState(false);
  const [activeImage, setActiveImage] = useState(0);
  const [qty, setQty] = useState(1);
  const [added, setAdded] = useState(false);

  useEffect(() => {
    if (!Number.isInteger(id) || id <= 0) {
      setNotFound(true);
      return;
    }
    let cancelled = false;
    fetch(`/api/products/${id}`)
      .then((res) => res.json())
      .then((json) => {
        if (cancelled) return;
        if (json.ok && json.data) {
          setProduct(json.data as Product);
          // Related: same category, excluding this product.
          const params = new URLSearchParams({ category: json.data.category, pageSize: '48' });
          return fetch(`/api/products?${params.toString()}`)
            .then((r) => r.json())
            .then((list) => {
              if (cancelled || !list.ok) return;
              const others = (list.data.items as Product[]).filter((p) => p.id !== id);
              setRelated(others.slice(0, 3));
            })
            .catch(() => undefined);
        }
        setNotFound(true);
      })
      .catch(() => setNotFound(true));
    return () => {
      cancelled = true;
    };
  }, [id]);

  const thumbnails = useMemo(
    () => (product ? galleryImages(product.image, product.category) : []),
    [product]
  );

  useEffect(() => {
    if (added) {
      const t = setTimeout(() => setAdded(false), 1500);
      return () => clearTimeout(t);
    }
  }, [added]);

  if (notFound) {
    return (
      <main id="main" className="mx-auto max-w-3xl px-4 py-24 text-center sm:px-6">
        <h1 className="text-3xl">Product not found</h1>
        <p className="mt-3 text-text-secondary">
          It may have been removed from the collection.
        </p>
        <Link href="/shop" className="btn btn-primary mt-8">
          Back to shop
        </Link>
      </main>
    );
  }

  if (!product) {
    return (
      <main id="main" className="mx-auto max-w-7xl px-4 py-24 text-center sm:px-6">
        <p className="text-text-secondary">Loading product…</p>
      </main>
    );
  }

  const outOfStock = product.stock <= 0;
  const reviews = pickReviews(product.id);
  const descriptionParagraphs = product.description.split('\n\n').filter(Boolean);

  const handleAdd = () => {
    if (outOfStock) return;
    addItem({
      id: product.id,
      name: product.name,
      price_cents: product.price_cents,
      image: product.image,
      slug: product.slug,
      maxQty: product.stock || 20,
      qty,
    });
    setAdded(true);
  };

  return (
    <main id="main" className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8">
      <nav aria-label="Breadcrumb" className="text-sm text-text-secondary">
        <Link href="/shop" className="hover:text-brand-700">
          Shop
        </Link>
        <span className="mx-2" aria-hidden="true">
          /
        </span>
        <span>{product.category}</span>
      </nav>

      <div className="mt-6 grid gap-10 lg:grid-cols-2">
        {/* Gallery */}
        <div>
          <div className="overflow-hidden rounded-xl border border-border bg-bg-secondary shadow-soft">
            <img
              src={thumbnails[activeImage] ?? product.image}
              alt={product.name}
              width={800}
              height={800}
              className="aspect-square w-full object-cover"
            />
          </div>
          {thumbnails.length > 1 && (
            <div className="mt-4 flex gap-3" role="group" aria-label="Product images">
              {thumbnails.map((img, i) => (
                <button
                  key={img + String(i)}
                  type="button"
                  onClick={() => setActiveImage(i)}
                  aria-label={`View image ${i + 1} of ${thumbnails.length}`}
                  aria-pressed={activeImage === i}
                  className={`min-h-[44px] overflow-hidden rounded-lg border-2 bg-bg-secondary transition-colors ${
                    activeImage === i ? 'border-brand-500' : 'border-transparent hover:border-border'
                  }`}
                >
                  <img src={img} alt="" width={96} height={96} className="h-24 w-24 object-cover" />
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Details */}
        <div>
          <p className="text-xs font-semibold uppercase tracking-[0.2em] text-text-secondary">
            {product.category}
          </p>
          <h1 className="mt-2 text-3xl sm:text-4xl">{product.name}</h1>

          <div className="mt-3 flex flex-wrap items-center gap-3">
            <Stars rating={product.rating} />
            <span className="text-sm text-text-secondary">{product.rating.toFixed(1)} · {reviews.length} reviews</span>
          </div>

          <p className="mt-4 text-3xl font-bold text-brand-500">{formatCents(product.price_cents)}</p>

          <p className="mt-3" aria-live="polite">
            {outOfStock ? (
              <span className="pill bg-text-secondary/10 text-text-secondary">Out of stock</span>
            ) : product.stock <= 5 ? (
              <span className="pill bg-warning/10 text-warning">Only {product.stock} left in stock</span>
            ) : (
              <span className="pill bg-success/10 text-success">In stock</span>
            )}
          </p>

          <div className="mt-6 space-y-4 text-text-secondary">
            {descriptionParagraphs.map((paragraph, i) => (
              <p key={i} className="leading-relaxed">
                {paragraph}
              </p>
            ))}
          </div>

          {/* Quantity + add to cart */}
          <div className="mt-8 flex flex-wrap items-end gap-4">
            <div>
              <label htmlFor="qty" className="label">
                Quantity
              </label>
              <div className="flex items-center rounded-full border border-border">
                <button
                  type="button"
                  className="min-h-[44px] min-w-[44px] rounded-l-full text-xl leading-none text-brand-700 hover:bg-brand-50 disabled:opacity-40"
                  onClick={() => setQty((v) => Math.max(1, v - 1))}
                  disabled={outOfStock || qty <= 1}
                  aria-label="Decrease quantity"
                >
                  −
                </button>
                <span className="min-w-[48px] text-center text-sm font-semibold" aria-live="polite">
                  {qty}
                </span>
                <button
                  type="button"
                  className="min-h-[44px] min-w-[44px] rounded-r-full text-xl leading-none text-brand-700 hover:bg-brand-50 disabled:opacity-40"
                  onClick={() => setQty((v) => Math.min(product.stock, v + 1))}
                  disabled={outOfStock || qty >= product.stock}
                  aria-label="Increase quantity"
                >
                  +
                </button>
              </div>
              <p className="mt-1 text-xs text-text-secondary">Max {Math.max(product.stock, 0)} per order</p>
            </div>

            <button
              type="button"
              className="btn btn-primary min-w-[220px] flex-1 sm:flex-none"
              onClick={handleAdd}
              disabled={outOfStock}
            >
              {outOfStock ? 'Out of stock' : added ? 'Added ✓' : 'Add to cart'}
            </button>
          </div>
        </div>
      </div>

      {/* Reviews */}
      <section className="mt-16 border-t border-border pt-12">
        <h2 className="text-2xl">Customer reviews</h2>
        <div className="mt-6 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {reviews.map((review) => (
            <article key={review.name} className="card p-6">
              <div className="flex items-center justify-between gap-2">
                <Stars rating={review.rating} size="sm" />
                <span className="text-xs text-text-secondary">{review.role}</span>
              </div>
              <p className="mt-3 text-sm leading-relaxed text-text-secondary">“{review.text}”</p>
              <p className="mt-4 text-sm font-semibold text-text-primary">{review.name}</p>
            </article>
          ))}
        </div>
      </section>

      {/* Related products */}
      {related.length > 0 && (
        <section className="mt-16 border-t border-border pt-12">
          <h2 className="text-2xl">Related products</h2>
          <div className="mt-6 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {related.map((p) => (
              <ProductCard key={p.id} product={p} />
            ))}
          </div>
        </section>
      )}
    </main>
  );
}

'use client';

import Link from 'next/link';
import { useCart } from '@/components/cart/cart-provider';
import { computeTotals, formatCents } from '@/lib/format';

export default function CartPage() {
  const { items, isHydrated, setQty, removeItem, subtotalCents } = useCart();
  const totals = computeTotals(subtotalCents);

  if (isHydrated && items.length === 0) {
    return (
      <main id="main" className="mx-auto max-w-3xl px-4 py-24 text-center sm:px-6">
        <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-bg-secondary">
          <svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="#5a4a42" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4Z" />
            <path d="M3 6h18" />
            <path d="M16 10a4 4 0 0 1-8 0" />
          </svg>
        </div>
        <h1 className="mt-6 text-3xl">Your cart is empty</h1>
        <p className="mt-3 text-text-secondary">
          Fancy adding something to it? Browse the collection and find a piece worth keeping.
        </p>
        <Link href="/shop" className="btn btn-primary mt-8">
          Continue shopping
        </Link>
      </main>
    );
  }

  return (
    <main id="main" className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8">
      <h1 className="text-3xl sm:text-4xl">Your cart</h1>

      <div className="mt-8 grid gap-10 lg:grid-cols-[1fr_340px]">
        {/* Items */}
        <div>
          {!isHydrated ? (
            <p className="text-text-secondary">Loading your cart…</p>
          ) : (
            <ul className="divide-y divide-border rounded-xl border border-border bg-white shadow-soft">
              {items.map((item) => (
                <li key={item.id} className="flex flex-wrap items-center gap-4 p-4 sm:flex-nowrap">
                  <Link href={`/product/${item.id}`} className="shrink-0">
                    <img
                      src={item.image}
                      alt={item.name}
                      width={80}
                      height={80}
                      className="h-20 w-20 rounded-lg bg-bg-secondary object-cover"
                    />
                  </Link>
                  <div className="min-w-0 flex-1">
                    <Link
                      href={`/product/${item.id}`}
                      className="font-display text-lg font-semibold text-text-primary hover:text-brand-600"
                    >
                      {item.name}
                    </Link>
                    <p className="text-sm text-text-secondary">{formatCents(item.price_cents)} each</p>
                  </div>

                  <div className="flex items-center rounded-full border border-border">
                    <button
                      type="button"
                      className="min-h-[44px] min-w-[44px] rounded-l-full text-xl leading-none text-brand-700 hover:bg-brand-50 disabled:opacity-40"
                      onClick={() => setQty(item.id, item.qty - 1)}
                      disabled={item.qty <= 1}
                      aria-label={`Decrease quantity of ${item.name}`}
                    >
                      −
                    </button>
                    <span className="min-w-[40px] text-center text-sm font-semibold" aria-live="polite">
                      {item.qty}
                    </span>
                    <button
                      type="button"
                      className="min-h-[44px] min-w-[44px] rounded-r-full text-xl leading-none text-brand-700 hover:bg-brand-50 disabled:opacity-40"
                      onClick={() => setQty(item.id, item.qty + 1)}
                      disabled={item.qty >= item.maxQty}
                      aria-label={`Increase quantity of ${item.name}`}
                    >
                      +
                    </button>
                  </div>

                  <p className="w-20 text-right font-semibold text-text-primary">
                    {formatCents(item.price_cents * item.qty)}
                  </p>

                  <button
                    type="button"
                    className="min-h-[44px] min-w-[44px] rounded-full text-text-secondary transition-colors hover:bg-error/5 hover:text-error"
                    onClick={() => removeItem(item.id)}
                    aria-label={`Remove ${item.name} from cart`}
                  >
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden="true">
                      <path d="M18 6 6 18M6 6l12 12" />
                    </svg>
                  </button>
                </li>
              ))}
            </ul>
          )}

          <Link href="/shop" className="btn btn-ghost mt-6">
            ← Continue shopping
          </Link>
        </div>

        {/* Summary */}
        <aside className="h-fit rounded-xl border border-border bg-bg-secondary p-6 lg:sticky lg:top-24">
          <h2 className="text-xl font-semibold">Order summary</h2>
          <dl className="mt-4 space-y-3 text-sm">
            <div className="flex justify-between">
              <dt className="text-text-secondary">Subtotal</dt>
              <dd className="font-medium">{formatCents(totals.subtotal_cents)}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-text-secondary">Shipping</dt>
              <dd className="font-medium">
                {totals.shipping_cents === 0 ? (
                  <span className="text-success">Free</span>
                ) : (
                  formatCents(totals.shipping_cents)
                )}
              </dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-text-secondary">Tax (8.5%)</dt>
              <dd className="font-medium">{formatCents(totals.tax_cents)}</dd>
            </div>
            <div className="flex justify-between border-t border-border pt-3 text-base">
              <dt className="font-semibold">Total</dt>
              <dd className="text-xl font-bold text-brand-800">{formatCents(totals.total_cents)}</dd>
            </div>
          </dl>
          {totals.shipping_cents > 0 && (
            <p className="mt-3 text-xs text-text-secondary">
              Free shipping when your subtotal reaches $100.
            </p>
          )}
          <Link
            href="/checkout"
            className="btn btn-primary mt-6 w-full"
            aria-disabled={items.length === 0}
          >
            Proceed to checkout
          </Link>
        </aside>
      </div>
    </main>
  );
}

'use client';

import { useCallback, useEffect, useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useCart } from '@/components/cart/cart-provider';
import { computeTotals, formatCents } from '@/lib/format';

type Errors = Partial<Record<string, string>>;

function validateField(name: string, value: string): string | null {
  const v = value.trim();
  switch (name) {
    case 'name':
      return v.length >= 2 ? null : 'Please enter your full name.';
    case 'email':
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) ? null : 'Please enter a valid email address.';
    case 'phone':
      return v.replace(/\D/g, '').length >= 7 ? null : 'Please enter a valid phone number.';
    case 'street':
      return v.length >= 3 ? null : 'Please enter your street address.';
    case 'city':
      return v.length >= 2 ? null : 'Please enter your city.';
    case 'state':
      return v.length >= 2 ? null : 'Please enter your state or region.';
    case 'zip':
      return v.length >= 3 ? null : 'Please enter your ZIP / postal code.';
    case 'card': {
      const digits = v.replace(/\D/g, '');
      return digits.length >= 13 && digits.length <= 19 ? null : 'Please enter a valid card number.';
    }
    case 'expiry': {
      const m = /^(0[1-9]|1[0-2])\/\d{2}$/.exec(v);
      if (!m) return 'Use MM/YY format.';
      return null;
    }
    case 'cvv': {
      const digits = v.replace(/\D/g, '');
      return digits.length >= 3 && digits.length <= 4 ? null : 'Please enter the 3 or 4 digit CVV.';
    }
    default:
      return null;
  }
}

export default function CheckoutPage() {
  const router = useRouter();
  const { items, subtotalCents, isHydrated, clearCart, saveOrder } = useCart();
  const totals = computeTotals(subtotalCents);

  const [values, setValues] = useState<Record<string, string>>({
    name: '',
    email: '',
    phone: '',
    street: '',
    city: '',
    state: '',
    zip: '',
    card: '',
    expiry: '',
    cvv: '',
  });
  const [errors, setErrors] = useState<Errors>({});
  const [serverError, setServerError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const setValue = useCallback((name: string, value: string) => {
    setValues((prev) => ({ ...prev, [name]: value }));
    setErrors((prev) => {
      if (!prev[name]) return prev;
      const next = { ...prev };
      delete next[name];
      return next;
    });
  }, []);

  const formatCard = useCallback((raw: string) => {
    const digits = raw.replace(/\D/g, '').slice(0, 16);
    return digits.replace(/(.{4})/g, '$1 ').trim();
  }, []);

  const formatExpiry = useCallback((raw: string) => {
    const digits = raw.replace(/\D/g, '').slice(0, 4);
    if (digits.length <= 2) return digits;
    return `${digits.slice(0, 2)}/${digits.slice(2)}`;
  }, []);

  const validateAll = useCallback((): Errors => {
    const next: Errors = {};
    for (const key of Object.keys(values)) {
      const message = validateField(key, values[key]);
      if (message) next[key] = message;
    }
    return next;
  }, [values]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (submitting) return;

    const nextErrors = validateAll();
    if (Object.keys(nextErrors).length > 0) {
      setErrors(nextErrors);
      return;
    }

    setSubmitting(true);
    setServerError(null);
    try {
      const res = await fetch('/api/orders', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          customer: {
            name: values.name,
            email: values.email,
            phone: values.phone,
          },
          shipping: {
            address_line: values.street,
            city: values.city,
            state: values.state,
            zip: values.zip,
          },
          items: items.map((i) => ({ product_id: i.id, qty: i.qty })),
        }),
      });
      const json = await res.json();
      if (json.ok && json.data) {
        saveOrder({ order: json.data.order, items: json.data.items });
        clearCart();
        router.push(`/order/${json.data.order.order_number}`);
        return;
      }
      setServerError(json.error || 'Something went wrong. Try again.');
    } catch {
      setServerError('Something went wrong. Try again.');
    } finally {
      setSubmitting(false);
    }
  };

  const formValid =
    values.name.trim().length >= 2 &&
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim()) &&
    values.phone.replace(/\D/g, '').length >= 7 &&
    values.street.trim().length >= 3 &&
    values.city.trim().length >= 2 &&
    values.state.trim().length >= 2 &&
    values.zip.trim().length >= 3 &&
    values.card.replace(/\D/g, '').length >= 13 &&
    /^(0[1-9]|1[0-2])\/\d{2}$/.test(values.expiry) &&
    values.cvv.replace(/\D/g, '').length >= 3;

  if (isHydrated && items.length === 0) {
    return (
      <main id="main" className="mx-auto max-w-3xl px-4 py-24 text-center sm:px-6">
        <h1 className="text-3xl">Nothing to check out</h1>
        <p className="mt-3 text-text-secondary">Your cart is empty.</p>
        <Link href="/shop" className="btn btn-primary mt-8">
          Continue shopping
        </Link>
      </main>
    );
  }

  return (
    <main id="main" className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8">
      <h1 className="text-3xl sm:text-4xl">Checkout</h1>

      {serverError && (
        <div
          className="mt-6 rounded-xl border border-error/25 bg-error/5 p-4 text-error"
          role="alert"
        >
