  { href: '/admin', label: 'Dashboard', icon: 'M3 13h8V3H3v10zm0 8h8v-6H3v6zm10 0h8V11h-8v10zm0-18v6h8V3h-8z' },
  { href: '/admin/orders', label: 'Orders', icon: 'M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4H6zM3 6h18M16 10a4 4 0 0 1-8 0' },
  { href: '/admin/products', label: 'Products', icon: 'M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16zM3.3 7 12 12l8.7-5M12 22V12' },
  { href: '/admin/settings', label: 'Settings', icon: 'M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6z' },
];

function NavIcon({ label, href }: { label: string; href: string }) {
  const d = NAV.find((n) => n.href === href)?.icon ?? '';
  return (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d={d} />
    </svg>
  );
}

export default function AdminShell({ children }: { children: ReactNode }) {
  const pathname = usePathname();
  const router = useRouter();
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [loggingOut, setLoggingOut] = useState(false);

  // Close the drawer on navigation.
  useEffect(() => {
    setDrawerOpen(false);
  }, [pathname]);

  // Close the drawer with Escape.
  useEffect(() => {
    if (!drawerOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setDrawerOpen(false);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [drawerOpen]);

  const handleLogout = async () => {
    setLoggingOut(true);
    try {
      await fetch('/api/admin/logout', { method: 'POST' });
    } finally {
      router.replace('/admin/login');
      router.refresh();
    }
  };

  const isActive = (href: string) =>
    href === '/admin' ? pathname === '/admin' : pathname.startsWith(href);

  const SidebarContent = (
    <nav aria-label="Admin" className="flex h-full flex-col gap-1">
      <p className="px-3 pb-4 pt-1 font-display text-xl font-semibold text-brand-800">
        Northlight
        <span className="block text-xs font-sans font-semibold uppercase tracking-[0.18em] text-text-secondary">
          Admin panel
        </span>
      </p>
      <ul className="space-y-1">
        {NAV.map((item) => (
          <li key={item.href}>
            <Link
              href={item.href}
              aria-current={isActive(item.href) ? 'page' : undefined}
              className={`flex min-h-[44px] items-center gap-3 rounded-lg px-3 text-sm font-medium transition-colors ${
                isActive(item.href)
                  ? 'bg-brand-100 text-brand-800'
                  : 'text-text-secondary hover:bg-brand-50 hover:text-brand-800'
              }`}
            >
              <NavIcon label={item.label} href={item.href} />
              {item.label}
            </Link>
          </li>
        ))}
      </ul>
      <div className="mt-auto">
        <button
          type="button"
          onClick={handleLogout}
          disabled={loggingOut}
          className="flex min-h-[44px] w-full items-center gap-3 rounded-lg px-3 text-sm font-medium text-text-secondary transition-colors hover:bg-error/5 hover:text-error"
        >
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9" />
          </svg>
          {loggingOut ? 'Signing out…' : 'Log out'}
        </button>
      </div>
    </nav>
  );

  return (
    <div className="min-h-screen bg-bg-secondary">
      {/* Desktop sidebar */}
      <aside className="fixed inset-y-0 left-0 z-30 hidden w-60 border-r border-border bg-white p-4 lg:block">
        {SidebarContent}
      </aside>

      {/* Mobile drawer */}
      {drawerOpen && (
        <div className="fixed inset-0 z-40 lg:hidden" role="presentation">
          <div
            className="absolute inset-0 bg-brand-900/40"
            onClick={() => setDrawerOpen(false)}
            aria-hidden="true"
          />
          <div
            className="absolute inset-y-0 left-0 w-72 bg-white p-4 shadow-lift"
            role="dialog"
            aria-modal="true"
            aria-label="Admin navigation"
          >
            <div className="flex justify-end">
              <button
                type="button"
                onClick={() => setDrawerOpen(false)}
                className="flex min-h-[44px] min-w-[44px] items-center justify-center rounded-full text-text-secondary hover:bg-brand-50"
                aria-label="Close navigation"
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden="true">
                  <path d="M18 6 6 18M6 6l12 12" />
                </svg>
              </button>
            </div>
            {SidebarContent}
          </div>
        </div>
      )}

      {/* Main column */}
      <div className="lg:pl-60">
        <header className="sticky top-0 z-20 flex h-16 items-center gap-3 border-b border-border bg-white/95 px-4 backdrop-blur sm:px-6">
          <button
            type="button"
            onClick={() => setDrawerOpen(true)}
            className="flex min-h-[44px] min-w-[44px] items-center justify-center rounded-full text-brand-800 hover:bg-brand-50 lg:hidden"
            aria-label="Open navigation"
            aria-expanded={drawerOpen}
            aria-controls="admin-drawer"
          >
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden="true">
              <path d="M4 6h16M4 12h16M4 18h16" />
            </svg>
          </button>
          <h1 className="text-lg font-semibold text-text-primary">Admin Panel</h1>
          <span className="ml-auto hidden sm:block">
            <span className="pill bg-success/10 text-success">
              <span className="h-1.5 w-1.5 rounded-full bg-success" aria-hidden="true" />
              Signed in
            </span>
          </span>
        </header>
        <main id="main" className="mx-auto max-w-6xl px-4 py-8 sm:px-6 lg:py-10">
          {children}
        </main>
      </div>
    </div>
  );
}

export type OrderStatusLabel = 'placed' | 'shipped' | 'cancelled';

const STYLES: Record<OrderStatusLabel, string> = {
  placed: 'bg-warning/10 text-warning',
  shipped: 'bg-success/10 text-success',
  cancelled: 'bg-text-secondary/10 text-text-secondary',
};

export default function StatusBadge({ status }: { status: string }) {
  const style = STYLES[status as OrderStatusLabel] ?? 'bg-text-secondary/10 text-text-secondary';
  return <span className={`pill ${style}`}>{status}</span>;
}

'use client';

import { useEffect, useRef } from 'react';

interface ConfirmDialogProps {
  open: boolean;
  title: string;
  message: string;
  confirmLabel?: string;
  onConfirm: () => void;
  onCancel: () => void;
}

/**
 * Accessible confirmation dialog built on the native <dialog> element
 * (focus trap + Escape handling come for free).
 */
export default function ConfirmDialog({
  open,
  title,
  message,
  confirmLabel = 'Delete',
  onConfirm,
  onCancel,
}: ConfirmDialogProps) {
  const ref = useRef<HTMLDialogElement>(null);

  useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    if (open && !dialog.open) {
      dialog.showModal();
    } else if (!open && dialog.open) {
      dialog.close();
    }
  }, [open]);

  return (
    <dialog
      ref={ref}
      onCancel={(e) => {
        e.preventDefault();
        onCancel();
      }}
      onClick={(e) => {
        if (e.target === ref.current) onCancel();
      }}
      className="m-auto w-[92vw] max-w-md rounded-xl border border-border bg-white p-6 shadow-lift backdrop:bg-brand-900/40"
      aria-labelledby="confirm-title"
    >
      <h2 id="confirm-title" className="text-xl font-semibold text-text-primary">
        {title}
      </h2>
      <p className="mt-2 text-sm leading-relaxed text-text-secondary">{message}</p>
      <div className="mt-6 flex flex-wrap justify-end gap-3">
        <button type="button" className="btn btn-secondary" onClick={onCancel} autoFocus>
          Cancel
        </button>
        <button type="button" className="btn btn-danger" onClick={onConfirm}>
          {confirmLabel}
        </button>
      </div>
    </dialog>
  );
}

'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';
import { formatCents, formatShortDate } from '@/lib/format';
import type { Order, OrderItem } from '@/lib/store';
import StatusBadge from '@/components/admin/status-badge';

interface OrderWithItems extends Order {
  items: OrderItem[];
}

interface Metrics {
  total_orders: number;
  revenue_cents: number;
  items_sold: number;
  avg_order_value_cents: number;
}

function computeMetrics(orders: OrderWithItems[]): Metrics {
  const active = orders.filter((o) => o.status !== 'cancelled');
  const revenue_cents = active.reduce((sum, o) => sum + o.total_cents, 0);
  const items_sold = active.reduce(
    (sum, o) => sum + o.items.reduce((s, i) => s + i.qty, 0),
    0
  );
  return {
    total_orders: active.length,
    revenue_cents,
    items_sold,
    avg_order_value_cents: active.length > 0 ? Math.round(revenue_cents / active.length) : 0,
  };
}

const CARD_STYLES = [
  'bg-white',
  'bg-brand-50',
  'bg-white',
  'bg-brand-100',
];

export default function AdminDashboard() {
  const [orders, setOrders] = useState<OrderWithItems[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetch('/api/orders')
      .then((res) => res.json())
      .then((json) => {
        if (cancelled) return;
        if (json.ok) {
          setOrders(json.data as OrderWithItems[]);
        } else {
          setError(json.error ?? 'Failed to load orders.');
        }
      })
      .catch(() => {
        if (!cancelled) setError('Could not load orders.');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const metrics = computeMetrics(orders);
  const cards = [
    { label: 'Total orders', value: String(metrics.total_orders) },
    { label: 'Revenue', value: formatCents(metrics.revenue_cents) },
    { label: 'Items sold', value: String(metrics.items_sold) },
    { label: 'Avg order value', value: formatCents(metrics.avg_order_value_cents) },
  ];
  const recent = orders.slice(0, 5);

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-semibold text-text-primary">Dashboard</h2>
          <p className="mt-1 text-sm text-text-secondary">
            A quick look at how the store is doing.
          </p>
        </div>
        <Link href="/admin/orders" className="btn btn-secondary">
          View all orders
        </Link>
      </div>

      {error ? (
        <div className="mt-8 rounded-xl border border-error/25 bg-error/5 p-5 text-error" role="alert">
          {error}
        </div>
      ) : loading ? (
        <p className="mt-8 text-text-secondary">Loading dashboard…</p>
      ) : (
        <>
          <div className="mt-8 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {cards.map((card, i) => (
              <div key={card.label} className={`card p-5 ${CARD_STYLES[i % CARD_STYLES.length]}`}>
                <p className="text-xs font-semibold uppercase tracking-wide text-text-secondary">
                  {card.label}
                </p>
                <p className="mt-2 text-2xl font-bold text-brand-800">{card.value}</p>
              </div>
            ))}
          </div>

          <section className="mt-10" aria-labelledby="recent-orders-heading">
            <h3 id="recent-orders-heading" className="text-xl font-semibold text-text-primary">
              Recent orders
            </h3>
            <div className="mt-4 overflow-hidden rounded-xl border border-border bg-white shadow-soft">
              <table className="w-full text-left text-sm">
                <thead className="bg-bg-secondary text-xs uppercase tracking-wide text-text-secondary">
                  <tr>
                    <th scope="col" className="px-4 py-3 font-semibold">Order</th>
                    <th scope="col" className="px-4 py-3 font-semibold hidden sm:table-cell">Customer</th>
                    <th scope="col" className="px-4 py-3 font-semibold">Date</th>
                    <th scope="col" className="px-4 py-3 font-semibold">Total</th>
                    <th scope="col" className="px-4 py-3 font-semibold">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {recent.map((order) => (
                    <tr key={order.id} className="hover:bg-brand-50/60">
                      <td className="px-4 py-3">
                        <Link href={`/admin/orders/${order.id}`} className="font-medium text-brand-700 hover:underline">
                          {order.order_number}
                        </Link>
                      </td>
                      <td className="px-4 py-3 text-text-secondary hidden sm:table-cell">
                        {order.customer_name}
                      </td>
                      <td className="px-4 py-3 text-text-secondary">{formatShortDate(order.created_at)}</td>
                      <td className="px-4 py-3 font-semibold">{formatCents(order.total_cents)}</td>
                      <td className="px-4 py-3">
                        <StatusBadge status={order.status} />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {recent.length === 0 && (
                <p className="px-4 py-8 text-center text-text-secondary">No orders yet.</p>
              )}
            </div>
          </section>
        </>
      )}
    </div>
  );
}

'use client';

import { useCallback, useEffect, useState } from 'react';
import Link from 'next/link';
import { formatCents, formatDateTime } from '@/lib/format';
import type { Order, OrderItem } from '@/lib/store';
import StatusBadge from '@/components/admin/status-badge';
import ConfirmDialog from '@/components/admin/confirm-dialog';

interface OrderWithItems extends Order {
  items: OrderItem[];
}

const FILTERS = ['all', 'placed', 'shipped', 'cancelled'] as const;

export default function AdminOrdersPage() {
  const [orders, setOrders] = useState<OrderWithItems[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filter, setFilter] = useState<(typeof FILTERS)[number]>('all');
  const [cancelTarget, setCancelTarget] = useState<OrderWithItems | null>(null);
  const [busyId, setBusyId] = useState<number | null>(null);

  const load = useCallback(() => {
    fetch('/api/orders')
      .then((res) => res.json())
      .then((json) => {
        if (json.ok) setOrders(json.data as OrderWithItems[]);
        else setError(json.error ?? 'Failed to load orders.');
      })
      .catch(() => setError('Could not load orders.'))
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const patchStatus = async (order: OrderWithItems, status: 'shipped' | 'cancelled') => {
    setBusyId(order.id);
    try {
      const res = await fetch(`/api/orders/${order.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status }),
      });
      const json = await res.json();
      if (json.ok) {
        setOrders((prev) =>
          prev.map((o) => (o.id === order.id ? { ...o, ...json.data } : o))
        );
      } else {
        setError(json.error ?? 'Could not update the order.');
      }
    } catch {
      setError('Network error — the order was not updated.');
    } finally {
      setBusyId(null);
      setCancelTarget(null);
    }
  };

  const visible = filter === 'all' ? orders : orders.filter((o) => o.status === filter);

  return (
    <div>
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-semibold text-text-primary">Orders</h2>
          <p className="mt-1 text-sm text-text-secondary">
            Confirm, ship, or cancel customer orders.
          </p>
        </div>
        <label htmlFor="order-filter" className="sr-only">
          Filter by status
        </label>
        <select
          id="order-filter"
          className="field min-h-[44px] w-auto"
          value={filter}
          onChange={(e) => setFilter(e.target.value as (typeof FILTERS)[number])}
        >
          {FILTERS.map((f) => (
            <option key={f} value={f}>
              {f === 'all' ? 'All statuses' : f.charAt(0).toUpperCase() + f.slice(1)}
            </option>
          ))}
        </select>
      </div>

      {error && (
        <div className="mt-6 rounded-xl border border-error/25 bg-error/5 p-4 text-error" role="alert">
          {error}
        </div>
      )}

      {loading ? (
        <p className="mt-8 text-text-secondary">Loading orders…</p>
      ) : (
        <div className="mt-6 overflow-x-auto rounded-xl border border-border bg-white shadow-soft">
          <table className="w-full min-w-[720px] text-left text-sm">
            <thead className="bg-bg-secondary text-xs uppercase tracking-wide text-text-secondary">
              <tr>
                <th scope="col" className="px-4 py-3 font-semibold">Order</th>
                <th scope="col" className="px-4 py-3 font-semibold">Customer</th>
                <th scope="col" className="px-4 py-3 font-semibold">Date</th>
                <th scope="col" className="px-4 py-3 font-semibold">Total</th>
                <th scope="col" className="px-4 py-3 font-semibold">Items</th>
                <th scope="col" className="px-4 py-3 font-semibold">Status</th>
                <th scope="col" className="px-4 py-3 text-right font-semibold">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {visible.map((order) => (
                <tr key={order.id} className="hover:bg-brand-50/60">
                  <td className="px-4 py-3">
                    <Link
                      href={`/admin/orders/${order.id}`}
                      className="font-medium text-brand-700 hover:underline"
                    >
                      {order.order_number}
                    </Link>
                  </td>
                  <td className="px-4 py-3">
                    <p className="font-medium text-text-primary">{order.customer_name}</p>
                    <p className="text-xs text-text-secondary">{order.email}</p>
                  </td>
                  <td className="px-4 py-3 text-text-secondary">{formatDateTime(order.created_at)}</td>
                  <td className="px-4 py-3 font-semibold">{formatCents(order.total_cents)}</td>
                  <td className="px-4 py-3 text-text-secondary">
                    {order.items.reduce((sum, i) => sum + i.qty, 0)}
                  </td>
                  <td className="px-4 py-3">
                    <StatusBadge status={order.status} />
                  </td>
                  <td className="px-4 py-3">
                    <div className="flex items-center justify-end gap-2">
                      <Link href={`/admin/orders/${order.id}`} className="btn btn-secondary btn-sm">
                        View
                      </Link>
                      {order.status === 'placed' && (
                        <button
                          type="button"
                          className="btn btn-primary btn-sm"
                          disabled={busyId === order.id}
                          onClick={() => patchStatus(order, 'shipped')}
                        >
                          Mark shipped
                        </button>
                      )}
                      {order.status !== 'cancelled' && (
                        <button
                          type="button"
                          className="btn btn-danger btn-sm"
                          disabled={busyId === order.id}
                          onClick={() => setCancelTarget(order)}
                        >
                          Cancel
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {visible.length === 0 && (
            <p className="px-4 py-10 text-center text-text-secondary">
              No {filter === 'all' ? '' : filter + ' '}orders to show.
            </p>
          )}
        </div>
      )}

      <ConfirmDialog
        open={Boolean(cancelTarget)}
        title="Cancel this order?"
        message={
          cancelTarget
            ? `Order ${cancelTarget.order_number} for ${cancelTarget.customer_name} (${formatCents(
                cancelTarget.total_cents
              )}) will be cancelled and its items returned to stock. This cannot be undone.`
            : ''
        }
        confirmLabel="Cancel order"
        onConfirm={() => {
          if (cancelTarget) patchStatus(cancelTarget, 'cancelled');
        }}
        onCancel={() => setCancelTarget(null)}
      />
    </div>
  );
}

'use client';

import { useCallback, useEffect, useState } from 'react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { formatCents, formatDateTime } from '@/lib/format';
import type { Order, OrderItem } from '@/lib/store';
import StatusBadge from '@/components/admin/status-badge';
import ConfirmDialog from '@/components/admin/confirm-dialog';

export default function AdminOrderDetailPage() {
  const params = useParams<{ id: string }>();
  const id = Number(params.id);

  const [order, setOrder] = useState<Order | null>(null);
  const [items, setItems] = useState<OrderItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [confirmCancel, setConfirmCancel] = useState(false);

  const load = useCallback(() => {
    fetch(`/api/orders/${id}`)
      .then((res) => res.json())
      .then((json) => {
        if (json.ok) {
          setOrder(json.data.order as Order);
          setItems(json.data.items as OrderItem[]);
        } else {
          setError(json.error ?? 'Order not found.');
        }
      })
      .catch(() => setError('Could not load this order.'))
      .finally(() => setLoading(false));
  }, [id]);

  useEffect(() => {
    load();
  }, [load]);

  const patchStatus = async (status: 'shipped' | 'cancelled') => {
    if (!order) return;
    setBusy(true);
    try {
      const res = await fetch(`/api/orders/${order.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status }),
      });
      const json = await res.json();
      if (json.ok) setOrder(json.data as Order);
      else setError(json.error ?? 'Could not update the order.');
    } catch {
      setError('Network error — the order was not updated.');
    } finally {
      setBusy(false);
      setConfirmCancel(false);
    }
  };

  if (loading) return <p className="text-text-secondary">Loading order…</p>;
  if (error || !order)
    return (
      <div>
        <div className="rounded-xl border border-error/25 bg-error/5 p-5 text-error" role="alert">
          {error ?? 'Order not found.'}
        </div>
        <Link href="/admin/orders" className="btn btn-secondary mt-6">
          Back to orders
        </Link>
      </div>
    );

  return (
    <div>
      <Link href="/admin/orders" className="btn btn-ghost">
        ← Back to orders
      </Link>

      <div className="mt-4 flex flex-wrap items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-semibold text-text-primary">{order.order_number}</h2>
          <p className="mt-1 text-sm text-text-secondary">Placed {formatDateTime(order.created_at)}</p>
        </div>
        <div className="flex items-center gap-3">
          <StatusBadge status={order.status} />
          {order.status === 'placed' && (
            <button
              type="button"
              className="btn btn-primary"
              disabled={busy}
