'use client';

import { formatNumber } from '@/lib/format';

interface TrendingItem {
  tag: string;
  posts: number;
  views: number;
  engagement: number;
}

export default function Trending({
  items,
  loading,
}: {
  items: TrendingItem[];
  loading: boolean;
}) {
  return (
    <section aria-label="Trending topics" className="min-w-0">
      <h2 className="text-xl font-semibold text-text-primary">Trending</h2>
      <div className="card mt-3 divide-y divide-border p-2">
        {loading
          ? [0, 1, 2, 3, 4].map((i) => (
              <div key={i} className="animate-pulse space-y-2 rounded-lg p-3">
                <div className="h-3 w-2/5 rounded bg-brand-100" />
                <div className="h-3 w-3/5 rounded bg-brand-100" />
              </div>
            ))
          : items.map((item, idx) => (
              <div key={item.tag} className="flex items-baseline justify-between gap-3 p-3">
                <div className="min-w-0">
                  <p className="flex items-baseline gap-2">
                    <span className="text-xs font-bold text-text-secondary">#{idx + 1}</span>
                    <span className="truncate font-semibold text-text-primary">#{item.tag}</span>
                  </p>
                  <p className="mt-0.5 text-xs text-text-secondary">
                    {item.posts} post{item.posts === 1 ? '' : 's'} · {formatNumber(item.views)} views
                  </p>
                </div>
                <span className="shrink-0 text-xs font-medium text-brand-700 dark:text-brand-100">
                  {formatNumber(item.engagement)}
                </span>
              </div>
            ))}
      </div>
    </section>
  );
}

'use client';

import { useEffect, useState } from 'react';
import {
  Area,
  AreaChart,
  CartesianGrid,
  Legend,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import { formatNumber, formatShortDay } from '@/lib/format';

interface SeriesPoint {
  date: string;
  views: number;
  engagement: number;
}

interface MetricsData {
  totals: { views: number; engagement: number; active_users: number };
  series: SeriesPoint[];
  trending: { tag: string; posts: number; views: number; engagement: number }[];
}

function tooltipLabel(date: string): string {
  return formatShortDay(date);
}

export default function AnalyticsPage() {
  const [metrics, setMetrics] = useState<MetricsData | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetch('/api/metrics')
      .then((res) => res.json())
      .then((json) => {
        if (cancelled) return;
        if (json.ok) setMetrics(json.data as MetricsData);
        else setError(json.error ?? 'Failed to load metrics.');
      })
      .catch(() => {
        if (!cancelled) setError('Could not load metrics.');
      });
    return () => {
      cancelled = true;
    };
  }, []);

  if (error) {
    return (
      <div className="rounded-xl border border-error/25 bg-error/5 p-5 text-error" role="alert">
        {error}
      </div>
    );
  }

  const series = metrics?.series ?? [];
  const totalViews = series.reduce((s, p) => s + p.views, 0);
  const totalEng = series.reduce((s, p) => s + p.engagement, 0);

  return (
    <div className="mx-auto max-w-4xl">
      <header>
        <h1 className="text-3xl font-semibold text-text-primary">7-day overview</h1>
        <p className="mt-1 text-sm text-text-secondary">
          Aggregate views and engagement across all content, updated live.
        </p>
      </header>

      {!metrics ? (
        <div className="card mt-6 h-80 animate-pulse" aria-label="Loading chart" />
      ) : (
        <>
          <div className="card mt-6 p-4 sm:p-6">
            <div className="flex flex-wrap items-baseline justify-between gap-2">
              <h2 className="text-xl font-semibold text-text-primary">Performance</h2>
              <p className="text-sm text-text-secondary">
                <span className="font-semibold text-text-primary">{totalViews.toLocaleString()}</span>{' '}
                views ·{' '}
                <span className="font-semibold text-text-primary">{totalEng.toLocaleString()}</span>{' '}
                engagement
              </p>
            </div>
            <div className="mt-4 h-72 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={series} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
                  <defs>
                    <linearGradient id="viewsFill" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor="#5a4a42" stopOpacity={0.32} />
                      <stop offset="100%" stopColor="#5a4a42" stopOpacity={0.02} />
                    </linearGradient>
                    <linearGradient id="engFill" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor="#b07d2b" stopOpacity={0.28} />
                      <stop offset="100%" stopColor="#b07d2b" stopOpacity={0.02} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e0ddd8" vertical={false} />
                  <XAxis
                    dataKey="date"
                    tickFormatter={formatShortDay}
                    tick={{ fill: '#6b6b6b', fontSize: 12 }}
                    stroke="#e0ddd8"
                    tickLine={false}
                    axisLine={false}
                  />
                  <YAxis
                    tickFormatter={formatNumber}
                    tick={{ fill: '#6b6b6b', fontSize: 12 }}
                    stroke="#e0ddd8"
                    tickLine={false}
                    axisLine={false}
                    width={44}
                  />
                  <Tooltip
                    contentStyle={{
                      borderRadius: 12,
                      border: '1px solid #e0ddd8',
                      fontSize: 13,
                    }}
                    labelFormatter={tooltipLabel}
                    formatter={(value: number | string | Array<number | string>, name: string) => [
                      formatNumber(Number(value)),
                      name === 'views' ? 'Views' : 'Engagement',
                    ]}
                  />
                  <Legend wrapperStyle={{ fontSize: 13 }} />
                  <Area
                    type="monotone"
                    dataKey="views"
                    stroke="#5a4a42"
                    strokeWidth={2}
                    fill="url(#viewsFill)"
                    dot={false}
                    activeDot={{ r: 5 }}
                    animationDuration={400}
                  />
                  <Area
                    type="monotone"
                    dataKey="engagement"
                    stroke="#b07d2b"
                    strokeWidth={2}
                    fill="url(#engFill)"
                    dot={false}
                    activeDot={{ r: 5 }}
                    animationDuration={400}
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className="mt-6 grid gap-4 sm:grid-cols-2">
            <div className="card p-5">
              <p className="text-xs font-semibold uppercase tracking-wide text-text-secondary">
                Best posting day
              </p>
              <p className="mt-2 text-2xl font-bold text-text-primary">
                {series.length
                  ? formatShortDay([...series].sort((a, b) => b.views - a.views)[0].date)
                  : '—'}
              </p>
            </div>
            <div className="card p-5">
              <p className="text-xs font-semibold uppercase tracking-wide text-text-secondary">
                Highest engagement rate
              </p>
              <p className="mt-2 text-2xl font-bold text-text-primary">
                {series.length
                  ? (() => {
                      const best = series
                        .filter((p) => p.views > 0)
                        .sort((a, b) => b.engagement / b.views - a.engagement / a.views)[0];
                      return best ? formatShortDay(best.date) : '—';
                    })()
                  : '—'}
              </p>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import {
  Area,
  AreaChart,
  CartesianGrid,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import { formatNumber, formatShortDay, timeAgo, formatDateLong } from '@/lib/format';

interface ContentDetail {
  id: number;
  handle: string;
  author: string;
  title: string;
  body: string;
  platform: string;
  tags: string;
  views: number;
  engagement: number;
  active_users: number;
  created_at: string;
}

interface SeriesPoint {
  date: string;
  views: number;
  engagement: number;
}

const PLATFORM_COLORS: Record<string, string> = {
  X: 'bg-[#1d1815] text-brand-50',
  Instagram: 'bg-warning text-white',
  LinkedIn: 'bg-success text-white',
};

export default function ContentDetailPage() {
  const params = useParams<{ id: string }>();
  const id = Number(params.id);

  const [content, setContent] = useState<ContentDetail | null>(null);
  const [series, setSeries] = useState<SeriesPoint[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetch(`/api/content/${id}`)
      .then((res) => res.json())
      .then((json) => {
        if (cancelled) return;
        if (json.ok) {
          setContent(json.data.content as ContentDetail);
          setSeries(json.data.series as SeriesPoint[]);
        } else {
          setError(json.error ?? 'Content not found.');
        }
      })
      .catch(() => {
        if (!cancelled) setError('Could not load this content.');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [id]);

  if (loading) {
    return <p className="text-text-secondary">Loading…</p>;
  }

  if (error || !content) {
    return (
      <div>
        <div className="rounded-xl border border-error/25 bg-error/5 p-5 text-error" role="alert">
          {error ?? 'Content not found.'}
        </div>
        <Link href="/dashboard" className="btn btn-secondary mt-6">
          Back to dashboard
        </Link>
      </div>
    );
  }

  const tags = content.tags.split(',').map((t) => t.trim()).filter(Boolean);

  return (
    <div className="mx-auto max-w-4xl">
      <Link href="/dashboard" className="btn btn-ghost">
        ← Dashboard
      </Link>

      <article className="card mt-4 p-6" aria-labelledby="content-title">
        <div className="flex flex-wrap items-center gap-2">
          <span className="font-semibold text-text-primary">{content.handle}</span>
          <span className="text-sm text-text-secondary">{content.author}</span>
          <span className={`pill ${PLATFORM_COLORS[content.platform] ?? 'bg-brand-100 text-brand-800'}`}>
            {content.platform}
          </span>
          <span className="ml-auto text-sm text-text-secondary">{timeAgo(content.created_at)}</span>
        </div>

        <h1 id="content-title" className="mt-3 font-display text-2xl font-semibold leading-snug text-text-primary sm:text-3xl">
          {content.title}
        </h1>
        <p className="mt-3 whitespace-pre-line text-base leading-relaxed text-text-secondary">
          {content.body}
        </p>

        <div className="mt-4 flex flex-wrap gap-2">
          {tags.map((tag) => (
            <span key={tag} className="pill bg-brand-100 text-brand-800">
              #{tag}
            </span>
          ))}
        </div>

        <p className="mt-4 text-xs text-text-secondary">Posted {formatDateLong(content.created_at)}</p>
      </article>

      <div className="mt-6 grid gap-4 sm:grid-cols-3">
        <div className="card p-5">
          <p className="text-xs font-semibold uppercase tracking-wide text-text-secondary">Views</p>
          <p className="mt-2 text-2xl font-bold text-text-primary tabular-nums">
            {formatNumber(content.views)}
          </p>
        </div>
        <div className="card p-5">
          <p className="text-xs font-semibold uppercase tracking-wide text-text-secondary">Engagement</p>
