                  <stop offset="100%" stopColor="#5a4a42" stopOpacity={0.02} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="#e0ddd8" vertical={false} />
              <XAxis
                dataKey="date"
                tickFormatter={formatShortDay}
                tick={{ fill: '#6b6b6b', fontSize: 12 }}
                stroke="#e0ddd8"
                tickLine={false}
                axisLine={false}
              />
              <YAxis
                tickFormatter={formatNumber}
                tick={{ fill: '#6b6b6b', fontSize: 12 }}
                stroke="#e0ddd8"
                tickLine={false}
                axisLine={false}
                width={44}
              />
              <Tooltip
                contentStyle={{ borderRadius: 12, border: '1px solid #e0ddd8', fontSize: 13 }}
                labelFormatter={(date: string) => formatShortDay(date)}
                formatter={(value: number | string | Array<number | string>, name: string) => [
                  formatNumber(Number(value)),
                  name === 'views' ? 'Views' : 'Engagement',
                ]}
              />
              <Area
                type="monotone"
                dataKey="views"
                stroke="#5a4a42"
                strokeWidth={2}
                fill="url(#detailViews)"
                dot={false}
                activeDot={{ r: 5 }}
                animationDuration={400}
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </section>
    </div>
  );
}

