  page?: number;
  pageSize?: number;
}): ProductListResult {
  const db = getDb();
  const page = Math.max(1, Number(params.page) || 1);
  const pageSize = Math.min(48, Math.max(1, Number(params.pageSize) || 12));

  const where: string[] = [];
  const args: Array<string | number> = [];

  if (params.category) {
    where.push('category = ?');
    args.push(params.category);
  }
  if (params.q) {
    where.push('(name LIKE ? OR description LIKE ?)');
    args.push(`%${params.q}%`, `%${params.q}%`);
  }

  const whereSql = where.length ? `WHERE ${where.join(' AND ')}` : '';
  const total = (
    db.prepare(`SELECT COUNT(*) AS n FROM products ${whereSql}`).get(...args) as { n: number }
  ).n;

  const items = db
    .prepare(
      `SELECT * FROM products ${whereSql}
       ORDER BY datetime(created_at) DESC, id DESC
       LIMIT ? OFFSET ?`
    )
    .all(...args, pageSize, (page - 1) * pageSize) as Product[];

  return {
    items,
    total,
    page,
    pageSize,
    totalPages: Math.max(1, Math.ceil(total / pageSize)),
    categories: getCategories(),
  };
}

