  formatCents,
  computeShipping,
  computeTax,
  computeTotals,
} from './format';
export { PRODUCT_IMAGES } from './catalog';

export type Category = string;

export interface Product {
  id: number;
  name: string;
  slug: string;
  description: string;
  price_cents: number;
  category: Category;
  image: string;
  stock: number;
  rating: number;
  created_at: string;
}

export interface Order {
  id: number;
  order_number: string;
  customer_name: string;
  email: string;
  phone: string;
  address_line: string;
  city: string;
  state: string;
  zip: string;
  status: 'placed' | 'shipped' | 'cancelled';
  subtotal_cents: number;
  shipping_cents: number;
  tax_cents: number;
  total_cents: number;
  created_at: string;
}

export interface OrderItem {
  id: number;
  order_id: number;
  product_id: number;
  name: string;
  unit_price_cents: number;
  qty: number;
  line_total_cents: number;
}

export const ORDER_STATUSES = ['placed', 'shipped', 'cancelled'] as const;
export type OrderStatus = (typeof ORDER_STATUSES)[number];

function normalizeSlug(name: string): string {
  const base = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '');
  return `${base}-${randomBytes(4).toString('hex')}`;
}

export function generateOrderNumber(): string {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let out = '';
  for (let i = 0; i < 6; i += 1) {
    out += chars[Math.floor(Math.random() * chars.length)];
  }
  return `ORD-${out}`;
}

// ---- Product queries ----

export function getCategories(): Category[] {
  const db = getDb();
  const rows = db
    .prepare('SELECT DISTINCT category FROM products ORDER BY category ASC')
    .all() as { category: string }[];
  return rows.map((r) => r.category);
}

export function getProductById(id: number): Product | null {
  const db = getDb();
  return (db.prepare('SELECT * FROM products WHERE id = ?').get(id) as Product) ?? null;
}

export function getProductBySlug(slug: string): Product | null {
  const db = getDb();
  return (db.prepare('SELECT * FROM products WHERE slug = ?').get(slug) as Product) ?? null;
}

export interface ProductListResult {
  items: Product[];
  total: number;

