export interface DashboardMetrics {
  total_orders: number;
  revenue_cents: number;
  items_sold: number;
  avg_order_value_cents: number;
}

export function getDashboardMetrics(): DashboardMetrics {
  const db = getDb();
  const totals = db
    .prepare(
      `SELECT COUNT(*) AS orders, COALESCE(SUM(total_cents), 0) AS revenue
       FROM orders WHERE status != 'cancelled'`
    )
    .get() as { orders: number; revenue: number };
  const items = db
    .prepare(
      `SELECT COALESCE(SUM(oi.qty), 0) AS n
       FROM order_items oi
       JOIN orders o ON o.id = oi.order_id
       WHERE o.status != 'cancelled'`
    )
    .get() as { n: number };
  const avg = totals.orders > 0 ? Math.round(totals.revenue / totals.orders) : 0;
  return {
    total_orders: totals.orders,
    revenue_cents: totals.revenue,
    items_sold: items.n,
    avg_order_value_cents: avg,
  };
}

