/** Last N days as 'YYYY-MM-DD' (local calendar), oldest -> newest. */
export function lastNDates(n: number): string[] {
  const out: string[] = [];
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  for (let i = n - 1; i >= 0; i -= 1) {
    const day = new Date(d);
    day.setDate(d.getDate() - i);
    out.push(localDate(day));
  }
  return out;
}

